import{d as g,C as e,o as u,c as h,a3 as i,E as a,j as t,a as d}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"论语·子罕","description":"《论语》第 9 篇「子罕」——三十一章原文与导读。子绝四、循循然善诱人、逝者如斯夫、岁寒知松柏、匹夫不可夺志。","frontmatter":{"title":"论语·子罕","description":"《论语》第 9 篇「子罕」——三十一章原文与导读。子绝四、循循然善诱人、逝者如斯夫、岁寒知松柏、匹夫不可夺志。","category":"guide","aliases":["子罕","子罕篇","子罕第九","论语的子罕","lunyu 子罕"],"source":["《论语》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/lunyu/chapter-09.md","filePath":"lizhimingde/sishu-wujing/lunyu/chapter-09.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/lunyu/chapter-09.md"},x=g({...m,setup(y){const s=[{id:"yi",label:"一、子罕言利，与命与仁",showLabel:!0,sentences:[["子罕言利，与命与仁。"]],note:"「子罕言利，与命与仁」——孔子很少谈利，却称许命与仁（与＝赞许、称许）。一说：很少谈利，只赞同命与仁。此章总说孔子言说之侧重。"},{id:"er",label:"二、博学而无所成名",showLabel:!0,sentences:[["达巷党人曰：“大哉孔子！博学而无所成名。”子闻之，谓门弟子曰：“吾何执？执御乎，执射乎？吾执",{text:"御",glossary:"yu-jia"},"矣。”"]],note:"达巷党人说：「大哉孔子！博学而无所成名」——孔子真伟大！学问广博却没有成名的专长。孔子闻之，对门弟子说：「吾何执？执御乎，执射乎？吾执御矣」——我专执什么呢？赶车呢，还是射箭？我还是赶车吧。自谦而带幽默。"},{id:"san",label:"三、麻冕，礼也；今也纯",showLabel:!0,sentences:[["子曰：“麻冕，礼也；今也",{text:"纯",glossary:"chun-si"},"，俭，吾从众。拜下，礼也；今拜乎上，",{text:"泰",glossary:"tai-ju"},"也；虽违众，吾从下。”"]],note:"「麻冕，礼也；今也纯，俭，吾从众」——用麻作礼帽是古礼，如今用丝（纯＝黑丝）较俭省，我随众人。「拜下，礼也；今拜乎上，泰也；虽违众，吾从下」——在堂下拜是古礼，如今在堂上拜是骄慢；虽违众人之俗，我仍从堂下拜。可见从众与违众，皆有准则。"},{id:"si",label:"四、子绝四",showLabel:!0,sentences:[["子绝四：毋意、毋必、毋固、毋我。"]],note:"「子绝四：毋意、毋必、毋固、毋我」——孔子杜绝四种毛病：不凭空猜测（意）、不绝对肯定（必）、不固执己见（固）、不自以为是（我）。此章极精，为孔子修养之要。"},{id:"wu",label:"五、文不在兹乎",showLabel:!0,sentences:[["子畏于匡，曰：“文王既没，文不在兹乎？天之将丧斯文也，后死者不得与于斯文也；天之未丧斯文也，",{text:"匡人",glossary:"kuangren"},"其如予何？”"]],note:"孔子在匡地被围，说：「文王既没，文不在兹乎」——文王已死，礼乐之文不就在我这里吗？「天之将丧斯文也，后死者不得与于斯文也」——天若将丧此文化，后人就不能参与其中了；「天之未丧斯文也，匡人其如予何」——天若未丧此文化，匡人能把我怎样？"},{id:"liu",label:"六、吾少也贱，故多能鄙事",showLabel:!0,sentences:[["太宰问于子贡曰：“夫子圣者与，何其多能也？”子贡曰：“固天纵之将圣，又多能也。”子闻之，曰：“太宰知我乎！吾少也贱，故多能鄙事。君子多乎哉？不多也。”"]],note:"太宰问子贡：「夫子圣者与，何其多能也」——夫子是圣人吧，何以这样多能？子贡答：「固天纵之将圣，又多能也」——本是天纵之使为圣，又使他多能。孔子闻之曰：「太宰知我乎！吾少也贱，故多能鄙事」——太宰了解我吗？我年少贫贱，故学会许多鄙事。「君子多乎哉？不多也」——君子需要这么多能吗？不需要。"},{id:"qi",label:"七、吾不试，故艺",showLabel:!0,sentences:[["牢曰：“子云：‘吾不试，故",{text:"艺",glossary:"yi-ji"},"。’”"]],note:"牢说：「子云：吾不试，故艺」——孔子说：我不被任用（试＝用），所以学会了许多技艺。"},{id:"ba",label:"八、空空如也",showLabel:!0,sentences:[["子曰：“吾有知乎哉？无知也。有鄙夫问于我，",{text:"空空如也",glossary:"kongkongru"},"。我",{text:"叩其两端",glossary:"kouqiliangduan"},"而竭焉。”"]],note:"「吾有知乎哉？无知也」——我有知识吗？没有知识。「有鄙夫问于我，空空如也。我叩其两端而竭焉」——有农夫来问，我心中空空（无所知）；但我从他问话的两端叩问推究，直到穷尽。见孔子之「无知」之虚与「叩两端」之法。"},{id:"jiu",label:"九、凤鸟不至，河不出图",showLabel:!0,sentences:[["子曰：“凤鸟不至，河不出图，吾已矣夫！”"]],note:"「凤鸟不至，河不出图，吾已矣夫」——凤凰不飞来、黄河不出图（皆为圣王之瑞），我大概没指望了！叹道之不行。"},{id:"shi",label:"十、虽少必作，过之必趋",showLabel:!0,sentences:[["子见",{text:"齐衰",glossary:"qicui"},"者、冕衣裳者与",{text:"瞽",glossary:"gu-mang"},"者，见之，虽少，必作，过之必趋。"]],note:"「子见齐衰者、冕衣裳者与瞽者，见之，虽少，必作，过之必趋」——孔子见穿丧服者、戴礼帽穿礼服者、以及盲人：见到时纵然对方年少也必起身（作＝起），经过时必快步而行（趋）。见其敬人之诚。"},{id:"shiyi",label:"十一、仰之弥高，钻之弥坚",showLabel:!0,sentences:[["颜渊",{text:"喟然",glossary:"kuiran"},"叹曰：“仰之弥高，钻之弥坚。瞻之在前，忽焉在后。夫子",{text:"循循然善诱人",glossary:"xunxunran"},"，博我以文，约我以礼，欲罢不能。既竭吾才，如有所立卓尔，虽欲从之，末由也已。”"]],note:"颜渊喟然叹曰：「仰之弥高，钻之弥坚」——老师的道，越仰望越显高，越钻研越显坚。「瞻之在前，忽焉在后」——看着在前，忽而在后。「夫子循循然善诱人，博我以文，约我以礼，欲罢不能」——老师循序渐进、善于引导，以文广博我，以礼约束我，想停下来也不能。「既竭吾才，如有所立卓尔，虽欲从之，末由也已」——竭尽我的才力，仿佛有个卓然高立之物，虽想追随，却无从入手。此章为颜渊论孔子之道最著名的一段。"},{id:"shier",label:"十二、吾谁欺？欺天乎",showLabel:!0,sentences:[["子疾病，子路使门人为臣。病间，曰：“久矣哉，由之行诈也！无臣而为有臣，吾谁欺？欺天乎？且予与其死于臣之手也，无宁死于二三子之手乎！且予纵不得大葬，予死于道路乎？”"]],note:"孔子病重，子路使门人充作家臣（为臣，以备丧礼）。病稍愈后，孔子说：「久矣哉，由之行诈也」——仲由行此诈伪已经很久了！「无臣而为有臣，吾谁欺？欺天乎」——本无家臣却装作有家臣，我欺骗谁？欺骗天吗？「且予与其死于臣之手也，无宁死于二三子之手乎」——与其死于家臣之手，宁死于你们这些学生之手。「且予纵不得大葬，予死于道路乎」——纵不得大葬，难道我会倒在路上无人管吗？"},{id:"shisan",label:"十三、我待贾者也",showLabel:!0,sentences:[["子贡曰：“有美玉于斯，",{text:"韫椟",glossary:"yundu"},"而藏诸？求善贾而",{text:"沽",glossary:"gu-mai"},"诸？”子曰：“沽之哉，沽之哉！我待贾者也。”"]],note:"子贡说：「有美玉于斯，韫椟而藏诸？求善贾而沽诸」——这里有一块美玉，是装进匣子收藏起来呢，还是找一个识货的商人卖掉？孔子答：「沽之哉，沽之哉！我待贾者也」——卖掉它！卖掉它！我正等待识货的人啊。喻己待时而仕。"},{id:"shisi",label:"十四、君子居之，何陋之有",showLabel:!0,sentences:[["子欲居九夷。或曰：“陋，如之何？”子曰：“君子居之，何陋之有！”"]],note:"孔子想住到九夷（东方边远之地）去。有人说：「陋，如之何」——那里鄙陋，怎么办？孔子说：「君子居之，何陋之有」——君子住在那儿，有什么鄙陋？"},{id:"shiwu",label:"十五、吾自卫反鲁，然后乐正",showLabel:!0,sentences:[["子曰：“吾自卫反鲁，然后乐正，《雅》《颂》各得其所。”"]],note:"「吾自卫反鲁，然后乐正，《雅》《颂》各得其所」——我从卫国回到鲁国，然后乐才得以厘正，《雅》《颂》各归其位。此孔子晚年整理《诗》乐之事的自述。"},{id:"shiliu",label:"十六、不为酒困",showLabel:!0,sentences:[["子曰：“出则事公卿，入则事父兄，丧事不敢不勉，不为酒困，何有于我哉？”"]],note:"「出则事公卿，入则事父兄，丧事不敢不勉，不为酒困，何有于我哉」——出外服事公卿，在家服事父兄，遇丧事不敢不勉力，不为酒所困：这些我做到了哪些呢？"},{id:"shiqi",label:"十七、逝者如斯夫",showLabel:!0,sentences:[["子在川上曰：“逝者如斯夫！不舍昼夜。”"]],note:"「子在川上曰：逝者如斯夫！不舍昼夜」——孔子在河边说：逝去的就像这流水啊！昼夜不停。喻时光之逝与为学之不已。"},{id:"shiba",label:"十八、吾未见好德如好色者也",showLabel:!0,sentences:[["子曰：“吾未见好德如好色者也。”"]],note:"「吾未见好德如好色者也」——我没见过好德如好色那般真切的人。"},{id:"shijiu",label:"十九、譬如为山",showLabel:!0,sentences:[["子曰：“譬如为山，未成一",{text:"篑",glossary:"kui"},"，止，吾止也；譬如平地，虽覆一篑，进，吾往也。”"]],note:"「譬如为山，未成一篑，止，吾止也」——好比堆山，只差一筐土便成，停下来，是我自己停的；「譬如平地，虽覆一篑，进，吾往也」——好比填平洼地，纵然只倒下一筐土，只要前进，是我自己前进的。言进退皆由己。"},{id:"ershi",label:"二十、语之而不惰者",showLabel:!0,sentences:[["子曰：“语之而不惰者，其回也与！”"]],note:"「语之而不惰者，其回也与」——听我讲说而毫不懈怠的，大概只有颜回吧！"},{id:"ershiyi",label:"二十一、吾见其进也",showLabel:!0,sentences:[["子谓颜渊，曰：“惜乎！吾见其进也，未见其止也。”"]],note:"孔子谓颜渊，曰：「惜乎！吾见其进也，未见其止也」——可惜啊！我只看见他不断前进，从未见他停下。"},{id:"ershier",label:"二十二、苗而不秀",showLabel:!0,sentences:[["子曰：“苗而不秀者有矣夫，秀而不实者有矣夫。”"]],note:"「苗而不秀者有矣夫，秀而不实者有矣夫」——长苗而不开花的，有吧；开花而不结果的，也有吧。喻为学之未成。"},{id:"ershisan",label:"二十三、后生可畏",showLabel:!0,sentences:[["子曰：“后生可畏，焉知来者之不如今也？四十、五十而无闻焉，斯亦不足畏也已。”"]],note:"「后生可畏，焉知来者之不如今也」——后生可畏，怎知后来者不如现在的人呢？「四十、五十而无闻焉，斯亦不足畏也已」——但到四五十岁仍默默无闻，那也就不足畏了。"},{id:"ershisi",label:"二十四、法语之言",showLabel:!0,sentences:[["子曰：“",{text:"法语之言",glossary:"fayuzhiyan"},"，能无从乎？改之为贵。",{text:"巽与之言",glossary:"xunyuzhiyan"},"，能无说乎？",{text:"绎",glossary:"yi-shu"},"之为贵。说而不绎，从而不改，吾末如之何也已矣。”"]],note:"「法语之言，能无从乎？改之为贵」——合乎正道之言，谁能不听从？但以能改过为贵。「巽与之言，能无说（悦）乎？绎之为贵」——谦顺之言，谁能不高兴？但以能寻绎其意为贵。「说而不绎，从而不改，吾末如之何也已矣」——只高兴而不寻绎、只听从而不改过，我对他也无可奈何了。"},{id:"ershiwu",label:"二十五、主忠信",showLabel:!0,sentences:[["子曰：“主忠信。毋友不如己者，过，则勿惮改。”"]],note:"「主忠信。毋友不如己者，过，则勿惮改」——以忠信为主；不要与不如己者交友；有了过错，便不要怕改。（与《学而》第八章略同。）"},{id:"ershiliu",label:"二十六、匹夫不可夺志",showLabel:!0,sentences:[["子曰：“三军可夺帅也，匹夫不可夺志也。”"]],note:"「三军可夺帅也，匹夫不可夺志也」——三军可夺其主帅，一个匹夫的志向却不可夺去。"},{id:"ershiqi",label:"二十七、不忮不求",showLabel:!0,sentences:[["子曰：“衣敝",{text:"缊袍",glossary:"yunpao"},"，与衣狐貉者立而不耻者，其由也与！‘不忮不求，何用不臧？’”子路终身诵之。子曰：“是道也，何足以臧？”"]],note:"「衣敝缊袍，与衣狐貉者立而不耻者，其由也与」——穿着破旧絮袍，与穿狐貉皮裘者并立而不觉羞耻的，大概只有仲由吧！引《诗》「不忮不求，何用不臧」（不嫉妒、不贪求，有何不好）。子路终身诵之。孔子曰：「是道也，何足以臧」——这只是道的一端，怎么够得上「好」呢？"},{id:"ershiba",label:"二十八、岁寒，然后知松柏之后凋也",showLabel:!0,sentences:[["子曰：“岁寒，然后知松柏之后",{text:"凋",glossary:"diao"},"也。”"]],note:"「岁寒，然后知松柏之后凋也」——到了岁寒，才知松柏是最后凋零的。喻逆境中乃见操守。"},{id:"ershijiu",label:"二十九、知者不惑",showLabel:!0,sentences:[["子曰：“知者不惑，仁者不忧，勇者不惧。”"]],note:"「知者不惑，仁者不忧，勇者不惧」——智者不迷惑，仁者不忧愁，勇者不畏惧。三者与《中庸》「三达德」相应。"},{id:"sanshi",label:"三十、可与共学",showLabel:!0,sentences:[["子曰：“可与共学，未可与",{text:"适道",glossary:"shidao"},"；可与适道，未可与立；可与立，未可与",{text:"权",glossary:"quan"},"。”"]],note:"「可与共学，未可与适道；可与适道，未可与立；可与立，未可与权」——可与之共学的人，未必可与之同道；可与同道者，未必可与之并立；可与并立者，未必可与之通权达变。四层递进，以「权」为最难。"},{id:"sanshiyi",label:"三十一、岂不尔思？室是远尔",showLabel:!0,sentences:[["“唐棣之华，偏其反而。岂不尔思？室是远尔。”子曰：“未之思也，夫何远之有？”"]],note:"引逸《诗》「唐棣之华，偏其反而。岂不尔思？室是远尔」——唐棣之花，翩翩摇动。难道我不想你吗？只是你住得太远了。孔子说：「未之思也，夫何远之有」——那是未曾真去想罢了；真去想，又有什么远呢？"}],r=[{id:"yu-jia",term:"御",pinyin:"yù",meaning:"驾车。达巷党人赞孔子博学而无专长，孔子自择「御」这种贱技，是自谦也是自嘲。"},{id:"chun-si",term:"纯",pinyin:"chún",meaning:"丝（此处指用丝做的礼帽）。麻冕改用丝，较省，孔子从众。"},{id:"tai-ju",term:"泰",pinyin:"tài",meaning:"骄泰、傲慢。堂下拜再升堂拜，是礼；只在堂上拜，是骄泰。孔子宁违众也要从礼。"},{id:"kuangren",term:"匡人",pinyin:"kuāng rén",meaning:"匡地的人。孔子过匡被误认作阳虎而遭围困，此语表示自信于文脉在身。"},{id:"yi-ji",term:"艺",pinyin:"yì",meaning:"技艺、技能。吾不试，故艺：我不被任用（做官），所以学了许多技艺。"},{id:"kongkongru",term:"空空如也",pinyin:"kōng kōng rú yě",meaning:"心里空空的、一无所知的样子。孔子自述面对提问时的虚心状态。"},{id:"kouqiliangduan",term:"叩其两端",pinyin:"kòu qí liǎng duān",meaning:"追问问题的正反两面。叩：叩问；两端：两头、正反。"},{id:"qicui",term:"齐衰",pinyin:"zī cuī",meaning:"古代丧服的一种（此指穿丧服的人）。"},{id:"gu-mang",term:"瞽",pinyin:"gǔ",meaning:"盲人（古时乐师多为盲者）。"},{id:"kuiran",term:"喟然",pinyin:"kuì rán",meaning:"感叹的样子。"},{id:"xunxunran",term:"循循然善诱人",pinyin:"xún xún rán shàn yòu rén",meaning:"有次序地一步步引导人。循循：有次序的样子；诱：引导。"},{id:"yundu",term:"韫椟",pinyin:"yùn dú",meaning:"藏在柜子里。韫：藏；椟：木柜。"},{id:"gu-mai",term:"沽",pinyin:"gū",meaning:"卖。求善贾而沽诸：找个识货的商人卖掉它吗？喻出仕。"},{id:"kui",term:"篑",pinyin:"kuì",meaning:"盛土的竹筐。未成一篑：只差一筐土。"},{id:"fayuzhiyan",term:"法语之言",pinyin:"fǎ yǔ zhī yán",meaning:"合乎礼法的正言规劝。"},{id:"xunyuzhiyan",term:"巽与之言",pinyin:"xùn yǔ zhī yán",meaning:"恭顺婉转的话。巽：顺。"},{id:"yi-shu",term:"绎",pinyin:"yì",meaning:"寻绎、推究其意。说而不绎：听了高兴却不深究。"},{id:"yunpao",term:"缊袍",pinyin:"yùn páo",meaning:"用乱麻旧絮做的袍子，指破旧之衣。"},{id:"diao",term:"凋",pinyin:"diāo",meaning:"凋零、衰落。后凋：最后才凋谢——松柏耐寒，见其操守。"},{id:"shidao",term:"适道",pinyin:"shì dào",meaning:"往道上去、趋向于道。"},{id:"quan",term:"权",pinyin:"quán",meaning:"通权达变、随机应变而不失原则。通权是修养的极高处。"}];return(p,n)=>{const o=e("DaoTextReading"),l=e("DaoKeywordCards");return u(),h("div",null,[n[0]||(n[0]=i('<h1 id="论语·子罕" tabindex="-1">论语·子罕 <a class="header-anchor" href="#论语·子罕" aria-label="Permalink to &quot;论语·子罕&quot;">​</a></h1><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2><p>《子罕》三十一章，前半多写<strong>孔子的自我认识</strong>与<strong>弟子的仰望</strong>，后半是格言式的短章。</p><p>开头「子罕言利，与命与仁」，一句就把孔子说话的分寸说清了。接着「子绝四：毋意、毋必、毋固、毋我」——<strong>四毋，是孔子修养的最高自述之一</strong>。第十一章颜渊那段感叹（仰之弥高、循循然善诱人），是所有弟子写老师最好的一段。</p><p>后半的短章，句句可独立成训：逝者如斯夫、吾未见好德如好色者、譬如为山、岁寒然后知松柏之后凋、知者不惑仁者不忧勇者不惧、三军可夺帅也匹夫不可夺志也、可与共学未可与适道。末章以「未之思也，夫何远之有」作结，与《述而》「我欲仁，斯仁至矣」同一路数。</p><p>默认竹简沉浸通读；切「经典阅读」可点生词。</p>',6)),a(o,{colophon:"子罕第九 · 三十一章",tone:"ink",sections:s,glossary:r,"default-mode":"slips","aria-label":"论语·子罕 原文"}),n[1]||(n[1]=t("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[d("【原典层】注音与字词 "),t("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),a(l,{items:[{term:"御",pinyin:["yù"],meaning:"驾车。达巷党人赞孔子博学而无专长，孔子自择「御」这种贱技，是自谦也是自嘲。"},{term:"纯",pinyin:["chún"],meaning:"丝（此处指用丝做的礼帽）。麻冕改用丝，较省，孔子从众。"},{term:"泰",pinyin:["tài"],meaning:"骄泰、傲慢。堂下拜再升堂拜，是礼；只在堂上拜，是骄泰。孔子宁违众也要从礼。"},{term:"匡人",pinyin:["kuāng","rén"],meaning:"匡地的人。孔子过匡被误认作阳虎而遭围困，此语表示自信于文脉在身。"},{term:"艺",pinyin:["yì"],meaning:"技艺、技能。吾不试，故艺：我不被任用（做官），所以学了许多技艺。"},{term:"空空如也",pinyin:["kōng","kōng","rú","yě"],meaning:"心里空空的、一无所知的样子。孔子自述面对提问时的虚心状态。"},{term:"叩其两端",pinyin:["kòu","qí","liǎng","duān"],meaning:"追问问题的正反两面。叩：叩问；两端：两头、正反。"},{term:"齐衰",pinyin:["zī","cuī"],meaning:"古代丧服的一种（此指穿丧服的人）。"},{term:"瞽",pinyin:["gǔ"],meaning:"盲人（古时乐师多为盲者）。"},{term:"喟然",pinyin:["kuì","rán"],meaning:"感叹的样子。"},{term:"循循然善诱人",pinyin:["xún","xún","rán","shàn","yòu","rén"],meaning:"有次序地一步步引导人。循循：有次序的样子；诱：引导。"},{term:"韫椟",pinyin:["yùn","dú"],meaning:"藏在柜子里。韫：藏；椟：木柜。"},{term:"沽",pinyin:["gū"],meaning:"卖。求善贾而沽诸：找个识货的商人卖掉它吗？喻出仕。"},{term:"篑",pinyin:["kuì"],meaning:"盛土的竹筐。未成一篑：只差一筐土。"},{term:"法语之言",pinyin:["fǎ","yǔ","zhī","yán"],meaning:"合乎礼法的正言规劝。"},{term:"巽与之言",pinyin:["xùn","yǔ","zhī","yán"],meaning:"恭顺婉转的话。巽：顺。"},{term:"绎",pinyin:["yì"],meaning:"寻绎、推究其意。说而不绎：听了高兴却不深究。"},{term:"缊袍",pinyin:["yùn","páo"],meaning:"用乱麻旧絮做的袍子，指破旧之衣。"},{term:"凋",pinyin:["diāo"],meaning:"凋零、衰落。后凋：最后才凋谢——松柏耐寒，见其操守。"},{term:"适道",pinyin:["shì","dào"],meaning:"往道上去、趋向于道。"},{term:"权",pinyin:["quán"],meaning:"通权达变、随机应变而不失原则。通权是修养的极高处。"}]}),n[2]||(n[2]=i('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>《子罕》三十一章，可以分成三层。<strong>一是孔子的自述</strong>：子绝四（毋意、毋必、毋固、毋我）、吾少也贱故多能鄙事、吾有知乎哉无知也、我不被任用所以学会技艺——<strong>他把自己说得很低</strong>。<strong>二是弟子的仰望</strong>：颜渊那段「仰之弥高，钻之弥坚」「循循然善诱人，博我以文，约我以礼，欲罢不能」，是全书最动人的师生关系记录。<strong>三是格言短章</strong>：逝者如斯夫、譬如为山、岁寒知松柏、匹夫不可夺志。</p><p>三者合起来，这一篇其实在讲<strong>修养的质地</strong>：它不显山露水（子罕言利与命与仁）、不固执（绝四）、不高看自己（少也贱），却在关键处极硬（匹夫不可夺志、松柏后凋）。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>「子绝四」是极高明的自我修养法</strong>：毋意（不猜）、毋必（不强求必成）、毋固（不固执）、毋我（不自以为是）——<strong>四条全是「减」，不是「加」</strong>。它不要求你多做什么，只要求你别多做什么。</li><li><strong>颜渊那一段把「好老师」写尽了</strong>：「循循然善诱人，博我以文，约我以礼，欲罢不能」——<strong>好的教，是让人自己想学下去，而不是逼着学</strong>。这也是《述而》「不愤不启」的实践样本。</li><li><strong>它把「时间的流逝」讲得最简</strong>：「逝者如斯夫！不舍昼夜」——不用一个「惜」字，而惜意全出。</li><li><strong>它给出一个「德」与「色」的锐利对照</strong>：「吾未见好德如好色者也」——<strong>承认人性有偏，才有修养的必要。</strong></li><li><strong>它把「坚持」的主权交还给个人</strong>：「譬如为山……止，吾止也；……进，吾往也」——<strong>进与止，责任都在自己</strong>，不在环境、不在他人。</li><li><strong>它区分了「守」与「通」</strong>：「可与立，未可与权」——<strong>守得住原则是一种境界，能在变化中守原则而不失分寸，是更高的境界。</strong></li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>练习「四毋」里最日常的两个</strong>：「毋意」（别猜别人怎么想）、「毋固」（别抱着自己的方案不放）。<strong>做决定前，先检查自己有没有预设前提。</strong></li><li><strong>用「欲罢不能」检验自己的学习方法</strong>：你学的东西，是越学越想学，还是靠逼自己？<strong>如果一直要靠意志硬撑，可能是方法或方向不对。</strong></li><li><strong>用「譬如为山」校准对「半途而废」的归因</strong>：停下来是因为外部条件，还是自己松了手？<strong>这句提醒的是——别把责任推给环境。</strong></li><li><strong>把「岁寒知松柏」用在长期关系与合作上</strong>：顺境里看不出人，<strong>艰难的时候才看得出谁还在</strong>。</li><li><strong>守住「匹夫不可夺志」这条底线</strong>：外部可以改变你的处境，不能改变你认定的事。<strong>这条底线是很多人在压力下唯一能握住的东西。</strong></li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>《子罕》这一篇里，孔子把姿态放得很低。</p><p>他说自己很少谈利、命、仁；说自己没有知识，别人来问，心里空空的，只是追问问题的两头；说自己年少贫贱，所以会许多粗活；说「我不被任用，所以学会了技艺」。弟子们仰望他的时候，他在说自己「无知」。</p><p>但同一篇里，他也有极硬的话：<strong>三军可以夺去主帅，一个普通人却不能被夺去志向</strong>；<strong>到了天寒，才知道松柏是最后凋零的</strong>。</p><p>还有一句是所有人都会读到的：<strong>「逝者如斯夫！不舍昼夜。」</strong>——他站在河岸上，只说了一句河水不停，两千五百年后的我们，还是听得懂那声叹息。</p><p>而写他这个人最好的，是弟子颜渊：「仰之弥高，钻之弥坚……夫子循循然善诱人，博我以文，约我以礼，欲罢不能。」</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「子绝四：毋意、毋必、毋固、毋我」——这四条里，我哪一条最容易犯？找个最近的例子。</li><li>「逝者如斯夫，不舍昼夜」——我第一次真正感觉到时间在流逝，是什么时候？那之后我改了什么？</li><li>「譬如为山……止，吾止也」——我放弃过的哪件事，其实是「吾止」，而不是外部条件不允许？</li><li>「岁寒，然后知松柏之后凋也」——过去一两年里，谁在我困难的时候还在？我又是谁的松柏？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-08">论语·泰伯</a>　下篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-10">论语·乡党</a></li><li>参考：《论语》朱熹《四书章句集注·论语集注》；杨伯峻《论语译注》</li></ul>',21))])}}});export{c as __pageData,x as default};
